insert into public.marketing_template_versions(id,template_id,version,structure,frequency_max_weekly,content_hash,created_by)values('c2320000-0000-4000-8000-000000000041',(select id from public.marketing_templates where template_key='PROBLEM_SOLUTION'),(select coalesce(max(version),0)+1 from public.marketing_template_versions where template_id=(select id from public.marketing_templates where template_key='PROBLEM_SOLUTION')),'{"hook":"h","body":"b","target_characters":100,"required_media":[],"allowed_ctas":[],"forbidden_claims":[],"translation_rules":{},"repetition_rules":{}}',8,repeat('f',64),'c2320000-0000-4000-8000-000000000001');
