('c2320000-0000-4000-8000-000000000061','c2320000-0000-4000-8000-000000000050','FACEBOOK','c2320000-0000-4000-8000-000000000041'),
('c2320000-0000-4000-8000-000000000062','c2320000-0000-4000-8000-000000000050','REEL','c2320000-0000-4000-8000-000000000041');
create temporary table p232(k text primary key,v jsonb);
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into p232 values('touch',public.register_verified_marketing_touch_v2('c2320000-0000-4000-8000-000000000002','ca232000-0000-4000-8000-000000000001','c2320000-0000-4000-8000-000000000050','c2320000-0000-4000-8000-000000000060','linkedin','social',repeat('a',64),clock_timestamp()+interval'29 days'));
select is((select v->>'outcome'from p232 where k='touch'),'MARKETING_TOUCH_CAPTURED','a server-verified touch is durably captured under its authenticated actor');
select throws_ok($$select public.ingest_marketing_attribution_event_v1('ca232000-0000-4000-8000-000000000001','c2320000-0000-4000-8000-000000000050','c2320000-0000-4000-8000-000000000060','CONTRACT_SIGNED','linkedin','social',repeat('a',64),999999,now(),'{}','p232-forged-legacy')$$,'42501','MARKETING_BUSINESS_SOURCE_REQUIRED','old generic ingestion cannot invent signed contracts or monetary value');
select throws_ok($$select public.record_marketing_business_conversion_v2('REGISTRATION_STARTED','cb232000-0000-4000-8000-000000000002',(select(v->>'touch_id')::uuid from p232 where k='touch'),'p232-foreign-registration')$$,'42501','MARKETING_BUSINESS_ACTOR_MISMATCH','a touch from one actor cannot claim another organization creator');
select throws_ok($$select public.record_marketing_business_conversion_v2('OPPORTUNITY_CREATED','ca232000-0000-4000-8000-000000000001',(select(v->>'touch_id')::uuid from p232 where k='touch'),'p232-forged-opportunity')$$,'P0002','MARKETING_BUSINESS_SOURCE_NOT_FOUND','a browser cookie and arbitrary UUID are never an opportunity source');
select is(public.record_marketing_business_conversion_v2('REGISTRATION_STARTED','ca232000-0000-4000-8000-000000000001',(select(v->>'touch_id')::uuid from p232 where k='touch'),'p232-real-registration')->>'outcome','MARKETING_BUSINESS_ATTRIBUTED','the actual organization creation is a verified registration conversion');
select is(public.record_marketing_business_conversion_v2('REGISTRATION_STARTED','ca232000-0000-4000-8000-000000000001',(select(v->>'touch_id')::uuid from p232 where k='touch'),'p232-other-cookie-retry')->>'outcome','MARKETING_BUSINESS_DEDUPLICATED','different retry keys cannot count the same business source twice');
select is((select count(*)from public.marketing_attribution_events where organization_id='ca232000-0000-4000-8000-000000000001'and event_type='REGISTRATION_STARTED'),1::bigint,'only one registration metric exists for the actual source');
select ok((select bool_and(source_hash~'^[0-9a-f]{64}$')from private.marketing_business_bindings_v2 binding join private.marketing_business_facts_v2 fact on fact.id=binding.fact_id where fact.source_id='ca232000-0000-4000-8000-000000000001'),'private attribution retains the immutable source evidence hash');
select ok((select bool_and(metadata='{}'::jsonb)from public.marketing_attribution_events where organization_id='ca232000-0000-4000-8000-000000000001'),'marketing tenant payloads expose no business organization IDs or private actor identifiers');
insert into public.organizations(id,legal_name,display_name,status,created_by)values('ca232000-0000-4000-8000-000000000003','Captured Customer232','Captured232','ACTIVE','c2320000-0000-4000-8000-000000000002');
select ok(exists(select 1 from private.marketing_business_facts_v2 fact join public.event_outbox event on event.aggregate_id=fact.id::text and event.event_type='MarketingBusinessFactReadyV2'where fact.event_type='REGISTRATION_STARTED'and fact.source_id='ca232000-0000-4000-8000-000000000003'),'source mutation and pending attribution fact are atomically durable');
select is((select count(*)from public.marketing_attribution_events where organization_id='ca232000-0000-4000-8000-000000000001'),1::bigint,'a queued fact is not claimed as a completed conversion');
select is(public.process_marketing_business_fact_v2((select id from private.marketing_business_facts_v2 where source_id='ca232000-0000-4000-8000-000000000003'and event_type='REGISTRATION_STARTED'))->>'outcome','MARKETING_BUSINESS_ATTRIBUTED','worker resumes the real fact using the durable pre-command touch without any browser cookie');
select set_config('request.jwt.claim.sub','c2320000-0000-4000-8000-000000000002',true);select set_config('request.jwt.claims','{"sub":"c2320000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
insert into p232 values('intake',public.save_public_diagnostic_intake('ca232000-0000-4000-8000-000000000001','{"goals":["secure_activity"],"sector":"commerce","team_size":"small","priority_tracking":"regular","sales_tracking":"shared","backup_restore":"recent","decision_trace":"systematic","next_action":"Review source controls"}','fr',repeat('f',64)));
select throws_ok($$select public.register_verified_marketing_touch_v2('c2320000-0000-4000-8000-000000000002','ca232000-0000-4000-8000-000000000001','c2320000-0000-4000-8000-000000000050','c2320000-0000-4000-8000-000000000060','linkedin','social',repeat('a',64),now()+interval'29 days')$$,'42501','MARKETING_ATTRIBUTION_WORKER_DENIED','tenant SQL cannot forge a server-verified touch');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(public.record_marketing_business_conversion_v2('DIAGNOSTIC_STARTED',(select(v->>'intake_id')::uuid from p232 where k='intake'),(select(v->>'touch_id')::uuid from p232 where k='touch'),'p232-diagnostic-start')->>'outcome','MARKETING_BUSINESS_ATTRIBUTED','real indicative intake persistence proves a diagnostic start without claiming a completed questionnaire');
select throws_ok($$select public.record_marketing_business_conversion_v2('OPPORTUNITY_CREATED',(select(v->>'intake_id')::uuid from p232 where k='intake'),(select(v->>'touch_id')::uuid from p232 where k='touch'),'p232-indicative-is-not-opportunity')$$,'P0002','MARKETING_BUSINESS_SOURCE_NOT_FOUND','an indicative intake cannot masquerade as an actual diagnostic opportunity');
-- Source fixtures below preserve all catalog foreign keys; entitlement is tested by the Client domain.
insert into public.catalog_libraries(id,code,slug,steward_organization_id,created_by)values('c2320000-0000-4000-8000-000000000100','LIB232','lib232','ca232000-0000-4000-8000-000000000001','c2320000-0000-4000-8000-000000000002');
