insert into public.catalog_subcategories(id,library_id,category_id,code,slug,created_by)values('c2320000-0000-4000-8000-000000000102','c2320000-0000-4000-8000-000000000100','c2320000-0000-4000-8000-000000000101','SUB232','sub232','c2320000-0000-4000-8000-000000000002');
insert into public.catalog_services(id,library_id,primary_subcategory_id,code,slug,created_by)values('c2320000-0000-4000-8000-000000000103','c2320000-0000-4000-8000-000000000100','c2320000-0000-4000-8000-000000000102','SERVICE232','service232','c2320000-0000-4000-8000-000000000002');
insert into public.service_requests(id,client_organization_id,library_id,service_id,created_by)values('c2320000-0000-4000-8000-000000000110','ca232000-0000-4000-8000-000000000001','c2320000-0000-4000-8000-000000000100','c2320000-0000-4000-8000-000000000103','c2320000-0000-4000-8000-000000000002');
insert into public.service_request_versions(id,request_id,client_organization_id,library_id,version_number,description,urgency,currency_code,required_quote_data,catalog_snapshot_hash,questionnaire_snapshot_hash,change_reason,content_hash,created_by)values('c2320000-0000-4000-8000-000000000111','c2320000-0000-4000-8000-000000000110','ca232000-0000-4000-8000-000000000001','c2320000-0000-4000-8000-000000000100',1,'Actual immutable request source232','NORMAL','EUR','{}',repeat('1',64),repeat('2',64),'Initial fixture source',repeat('3',64),'c2320000-0000-4000-8000-000000000002');
update public.service_requests set current_version_id='c2320000-0000-4000-8000-000000000111'where id='c2320000-0000-4000-8000-000000000110';
select is(public.process_marketing_business_fact_v2((select id from private.marketing_business_facts_v2 where event_type='RFQ_STARTED'and source_id='c2320000-0000-4000-8000-000000000110'))->>'outcome','MARKETING_BUSINESS_ATTRIBUTED','worker records RFQ start only from the actual immutable initial request version');
select ok((select binding.source_hash=private.canonical_request_hash(jsonb_build_object('request_id','c2320000-0000-4000-8000-000000000110'::uuid,'initial_version_hash',repeat('3',64)))from private.marketing_business_bindings_v2 binding join private.marketing_business_facts_v2 fact on fact.id=binding.fact_id where fact.event_type='RFQ_STARTED'and fact.source_id='c2320000-0000-4000-8000-000000000110'),'request attribution binds its canonical initial version hash');
select throws_ok($$select public.process_marketing_contract_conversion_v2('c2320000-0000-4000-8000-000000000110')$$,'55000','MARKETING_VERIFIED_CONTRACT_SIGNATURE_REQUIRED','request source cannot stand in for a sealed completed contract envelope');
select throws_ok($$select public.record_marketing_business_conversion_v2('CONTRACT_SIGNED','c2320000-0000-4000-8000-000000000110',(select(v->>'touch_id')::uuid from p232 where k='touch'),'p232-browser-signature')$$,'42501','MARKETING_BUSINESS_SOURCE_REQUIRED','browser completion helper cannot create a contract conversion');
insert into public.marketing_consents(organization_id,purpose,decision,policy_version,evidence_hash,decided_by)values('ca232000-0000-4000-8000-000000000001','MARKETING_ANALYTICS','WITHDRAWN','V4.1',repeat('b',64),'c2320000-0000-4000-8000-000000000002');
insert into public.organizations(id,legal_name,display_name,status,created_by)values('ca232000-0000-4000-8000-000000000004','Withdrawn232','Withdrawn232','ACTIVE','c2320000-0000-4000-8000-000000000002');
select is(public.process_marketing_business_fact_v2((select id from private.marketing_business_facts_v2 where source_id='ca232000-0000-4000-8000-000000000004'and event_type='REGISTRATION_STARTED'))->>'outcome','MARKETING_BUSINESS_SKIPPED_CONSENT','withdrawn consent blocks a queued conversion before ingestion');
select ok(not exists(select 1 from private.marketing_business_bindings_v2 binding join private.marketing_business_facts_v2 fact on fact.id=binding.fact_id where fact.source_id='ca232000-0000-4000-8000-000000000004'),'consent refusal creates no attributed binding');
select ok(not has_table_privilege('service_role','private.marketing_business_bindings_v2','INSERT')and not has_function_privilege('authenticated','public.process_marketing_business_fact_v2(uuid)','EXECUTE')and not has_function_privilege('service_role','private.ingest_marketing_attribution_core_v2(uuid,uuid,uuid,text,text,text,text,bigint,timestamptz,jsonb,text,character,uuid)','EXECUTE'),'narrow worker commands cannot bypass source verification through direct writes or generic conversion core');
select*from finish();rollback;
